def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import sys
    from collections import defaultdict

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table with -sys.maxsize
    dp = [[[[-sys.maxsize] * 2 for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]
    dp[1][1][1][1] = grid[0][0]

    # Fill the DP table
    for i1 in range(1, N+1):
        for j1 in range(1, N+1):
            for i2 in range(1, N+1):
                j2 = i1 + j1 - i2
                if j2 < 1 or j2 > N or grid[i1-1][j1-1] == -1 or grid[i2-1][j2-1] == -1:
                    continue
                current_value = grid[i1-1][j1-1]
                if i1 != i2 or j1 != j2:
                    current_value += grid[i2-1][j2-1]
                max_prev = max(dp[i1-1][j1][i2-1][j2], dp[i1-1][j1][i2][j2-1],
                               dp[i1][j1-1][i2-1][j2], dp[i1][j1-1][i2][j2-1])
                if max_prev != -sys.maxsize:
                    dp[i1][j1][i2][j2] = max_prev + current_value

    # The result is the maximum value in dp[N][N][N][N] or 0 if no valid path found
    return max(dp[N][N][N][N], 0)

