def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        isbn = isbn.replace('-', '')
        total = 0
        for i in range(9):
            total += (i + 1) * int(isbn[i])
        checksum = total % 11
        return 'X' if checksum == 10 else str(checksum)

    try:
        if len(isbn) != 13 or '-' not in isbn:
            raise ValueError("Invalid ISBN format")

        parts = isbn.split('-')
        if len(parts) != 4 or len(parts[0]) != 1 or len(parts[1]) != 3 or len(parts[2]) != 5 or len(parts[3]) != 1:
            raise ValueError("Invalid ISBN format")

        expected_checksum = calculate_checksum(isbn)
        provided_checksum = parts[3].upper()

        if expected_checksum == provided_checksum:
            return "Right"
        else:
            return f"{parts[0]}-{parts[1]}-{parts[2]}-{expected_checksum}"
    except ValueError as e:
        return str(e)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    try:
        if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
            raise ValueError("Invalid input dimensions or numbers of aisles/pairs.")
        if K > M or L > N:
            raise ValueError("Number of aisles cannot exceed the number of rows or columns.")

        # Count the number of chatting pairs that would be separated by an aisle at each position
        horizontal_separations = [0] * (M + 1)  # Including the row after the last row
        vertical_separations = [0] * (N + 1)    # Including the column after the last column

        for (Xi, Yi), (Pi, Qi) in chatting_pairs:
            if not (1 <= Xi <= M and 1 <= Yi <= N and 1 <= Pi <= M and 1 <= Qi <= N):
                raise ValueError("Chatting pair positions are out of the classroom bounds.")

            if Xi == Pi:  # Same row, separated by a vertical aisle
                if Yi < Qi:
                    vertical_separations[Yi] += 1
                else:
                    vertical_separations[Qi] += 1
            elif Yi == Qi:  # Same column, separated by a horizontal aisle
                if Xi < Pi:
                    horizontal_separations[Xi] += 1
                else:
                    horizontal_separations[Pi] += 1

        # Find the K best horizontal and L best vertical positions
        best_horizontal = sorted(range(1, M + 1), key=lambda x: horizontal_separations[x], reverse=True)[:K]
        best_vertical = sorted(range(1, N + 1), key=lambda x: vertical_separations[x], reverse=True)[:L]

        return (' '.join(map(str, best_horizontal)), ' '.join(map(str, best_vertical)))

    except Exception as e:
        return (str(e), str(e))

