def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or not isinstance(coeffs, list) or len(coeffs) != n + 1:
        raise ValueError("Invalid input: n must be an integer and coeffs must be a list of length n+1.")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign part
        if coeff > 0:
            sign = '+' if terms else ''
        else:
            sign = '-'

        # Determine the coefficient part
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine the variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        # Combine parts
        terms.append(f'{sign}{coeff_str}{var_str}')

    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig

    try:
        decoded_message = ''.join(mapping[char] for char in message)
    except KeyError:
        return "Failed"

    return decoded_message

