def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder traversals must be of the same length and valid.")

    def build_tree(in_start, in_end, post_start, post_end):
        if in_start > in_end or post_start > post_end:
            return None

        root_value = postorder[post_end]
        root_index = inorder.index(root_value)

        left_tree_size = root_index - in_start

        root = TreeNode(root_value)
        root.left = build_tree(in_start, root_index - 1, post_start, post_start + left_tree_size - 1)
        root.right = build_tree(root_index + 1, in_end, post_start + left_tree_size, post_end - 1)

        return root

    def preorder(node):
        if not node:
            return ""
        return node.val + preorder(node.left) + preorder(node.right)

    class TreeNode:
        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None

    root = build_tree(0, len(inorder) - 1, 0, len(postorder) - 1)
    return preorder(root)

