    if n == 0:
        return 0

    # Arrays to store the length of the longest increasing subsequence (LIS) ending at each index
    lis = [1] * n
    # Arrays to store the length of the longest decreasing subsequence (LDS) starting at each index
    lds = [1] * n

    # Fill lis array
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Fill lds array
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Find the maximum value of lis[i] + lds[i] - 1
    max_formation_length = 0
    for i in range(n):
        max_formation_length = max(max_formation_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum formation length
    return n - max_formation_length

def sort_students(student_scores):
    try:
        # Sort primarily by total score (descending), then by Chinese score (descending), and finally by student number (ascending)
        sorted_students = sorted(student_scores, key=lambda x: (-x[1], -x[2], x[0]))
        return sorted_students
    except Exception as e:
        # Handle unexpected errors gracefully
        print(f"An error occurred: {e}")
        return []

def min_groups(w, n, prices):
    if w <= 0:
        raise ValueError("The maximum allowed sum of prices for any group (w) must be greater than 0.")
    if n <= 0:
        raise ValueError("The total number of souvenirs (n) must be greater than 0.")
    if len(prices) != n:
        raise ValueError("The length of prices list must be equal to the total number of souvenirs (n).")
    if any(price > w for price in prices):
        raise ValueError("No single souvenir price can exceed the maximum allowed sum of prices for any group (w).")

    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be a positive integer.")

    # Base case for n=1
    if n == 1:
        return 2

    # Initialize the number of moves for 1 pair of discs
    previous_moves = 2

    # Iteratively compute the number of moves for each number of pairs up to n
    for i in range(2, n + 1):
        current_moves = 3 * previous_moves + 2
        previous_moves = current_moves

    return previous_moves

def total_smoked_cigarettes(n, k):
    if n < 0 or k <= 1:
        raise ValueError("Invalid input: n must be non-negative and k must be greater than 1.")

    total_smoked = n
    butts = n

    while butts >= k:
        new_cigarettes = butts // k
        total_smoked += new_cigarettes
        butts = butts % k + new_cigarettes

    return total_smoked
